<?php require_once __DIR__.'/../includes/permissions.php'; require_once __DIR__.'/../includes/csrf.php'; require_login();
$pdo=db();$metrics=['surveys'=>(int)$pdo->query('SELECT COUNT(*) FROM surveys')->fetchColumn(),'active_surveys'=>(int)$pdo->query("SELECT COUNT(*) FROM surveys WHERE status='active'")->fetchColumn(),'responses'=>(int)$pdo->query('SELECT COUNT(*) FROM survey_responses WHERE submitted_at IS NOT NULL')->fetchColumn(),'feedback'=>(int)$pdo->query('SELECT COUNT(*) FROM anonymous_feedback')->fetchColumn(),'open_feedback'=>(int)$pdo->query("SELECT COUNT(*) FROM anonymous_feedback WHERE status IN ('new','under_review')")->fetchColumn()];
$trend=$pdo->query("SELECT DATE(submitted_at) day,COUNT(*) total FROM survey_responses WHERE submitted_at>=DATE_SUB(CURDATE(),INTERVAL 13 DAY) GROUP BY DATE(submitted_at) ORDER BY day")->fetchAll();$feedbackStatus=$pdo->query('SELECT status,COUNT(*) total FROM anonymous_feedback GROUP BY status')->fetchAll();$surveys=$pdo->query("SELECT s.*,(SELECT COUNT(*) FROM survey_responses r WHERE r.survey_id=s.id AND r.submitted_at IS NOT NULL) response_count FROM surveys s ORDER BY s.created_at DESC LIMIT 8")->fetchAll();$feedback=$pdo->query('SELECT f.*,d.name department,c.name category FROM anonymous_feedback f JOIN departments d ON d.id=f.department_id LEFT JOIN feedback_categories c ON c.id=f.category_id ORDER BY f.created_at DESC LIMIT 8')->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=e(csrf_token())?>"><title>Dashboard — <?=e(APP_NAME)?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="container-fluid"><div class="row"><aside class="col-lg-2 sidebar p-3"><div class="fs-4 fw-bold text-white mb-4 px-2">Pulse<span class="text-primary">Point</span></div><a class="active" href="dashboard.php"><i class="bi bi-grid me-2"></i>Dashboard</a><a href="survey-builder.php"><i class="bi bi-ui-checks-grid me-2"></i>Survey builder</a><a href="#feedbackSection"><i class="bi bi-chat-square-text me-2"></i>Feedback</a><a href="../api/exports.php?type=feedback"><i class="bi bi-download me-2"></i>Export feedback</a><a href="../api/exports.php?type=responses"><i class="bi bi-file-earmark-spreadsheet me-2"></i>Export responses</a><hr class="border-secondary"><a href="index.php"><i class="bi bi-globe me-2"></i>Public site</a><button id="logoutBtn" class="btn btn-link text-start text-secondary text-decoration-none w-100"><i class="bi bi-box-arrow-left me-2"></i>Sign out</button></aside><main class="col-lg-10 p-4 p-xl-5"><div class="d-flex flex-wrap justify-content-between align-items-center mb-4 gap-3"><div><div class="text-secondary small">ADMIN PORTAL</div><h1 class="h2 fw-bold mb-0">Good day, <?=e(current_user()['name'])?></h1></div><a href="survey-builder.php" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i> New survey</a></div>
<div class="row g-3 mb-4"><div class="col-md-6 col-xl"><div class="metric"><div class="text-secondary">Surveys</div><div class="value"><?=$metrics['surveys']?></div><small><?=$metrics['active_surveys']?> active</small></div></div><div class="col-md-6 col-xl"><div class="metric"><div class="text-secondary">Responses</div><div class="value"><?=$metrics['responses']?></div><small>All submitted surveys</small></div></div><div class="col-md-6 col-xl"><div class="metric"><div class="text-secondary">Feedback</div><div class="value"><?=$metrics['feedback']?></div><small><?=$metrics['open_feedback']?> need attention</small></div></div></div>
<div class="row g-4 mb-4"><div class="col-xl-8"><div class="panel bg-white p-4"><h5 class="fw-bold">Response activity</h5><canvas id="responseChart" height="100"></canvas></div></div><div class="col-xl-4"><div class="panel bg-white p-4"><h5 class="fw-bold">Feedback status</h5><canvas id="feedbackChart"></canvas></div></div></div>
<div class="panel bg-white p-4 mb-4"><div class="d-flex justify-content-between align-items-center mb-3"><h5 class="fw-bold mb-0">Recent surveys</h5><a href="survey-builder.php" class="small">Create survey</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Survey</th><th>Status</th><th>Responses</th><th>Link</th><th></th></tr></thead><tbody><?php foreach($surveys as $s):?><tr><td><strong><?=e($s['title'])?></strong><div class="small text-secondary"><?=e(date('M j, Y',strtotime($s['created_at'])))?></div></td><td><span class="badge <?= $s['status']==='active'?'text-bg-success':($s['status']==='closed'?'text-bg-secondary':'text-bg-warning')?>"><?=e(ucfirst($s['status']))?></span></td><td><?=$s['response_count']?></td><td><a target="_blank" href="survey.php?token=<?=e($s['public_token'])?>">Open</a></td><td><a class="btn btn-sm btn-outline-primary" href="survey-builder.php?id=<?=$s['id']?>">Edit</a></td></tr><?php endforeach;?><?php if(!$surveys):?><tr><td colspan="5" class="empty-state">No surveys yet.</td></tr><?php endif;?></tbody></table></div></div>
<div id="feedbackSection" class="panel bg-white p-4"><div class="d-flex flex-wrap justify-content-between align-items-center mb-3"><h5 class="fw-bold mb-0">Latest anonymous feedback</h5><a href="../api/exports.php?type=feedback" class="btn btn-sm btn-outline-secondary">Export CSV</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Department</th><th>Feedback</th><th>Sentiment</th><th>Status</th></tr></thead><tbody><?php foreach($feedback as $f):?><tr><td><?=e($f['department'])?><div class="small text-secondary"><?=e($f['category']?:'Uncategorized')?></div></td><td style="max-width:520px"><div class="feedback-message"><?=e(mb_strimwidth($f['feedback_text'],0,180,'…'))?></div><small class="text-secondary"><?=e(date('M j, Y g:i A',strtotime($f['created_at'])))?></small></td><td><span class="badge rounded-pill <?= $f['sentiment']==='positive'?'text-bg-success':($f['sentiment']==='negative'?'text-bg-danger':'text-bg-secondary')?>"><?=e($f['sentiment'])?></span></td><td><select class="form-select form-select-sm feedback-status" data-id="<?=$f['id']?>"><option value="new" <?=$f['status']==='new'?'selected':''?>>New</option><option value="under_review" <?=$f['status']==='under_review'?'selected':''?>>Under review</option><option value="resolved" <?=$f['status']==='resolved'?'selected':''?>>Resolved</option><option value="archived" <?=$f['status']==='archived'?'selected':''?>>Archived</option></select></td></tr><?php endforeach;?><?php if(!$feedback):?><tr><td colspan="4" class="empty-state">No feedback submitted yet.</td></tr><?php endif;?></tbody></table></div></div></main></div></div>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script><script src="assets/js/app.js"></script><script>window.dashboardData=<?=json_encode(['response_trend'=>$trend,'feedback_by_status'=>$feedbackStatus])?>;</script><script src="assets/js/dashboard.js"></script><script>$('#logoutBtn').on('click',()=>$.ajax({url:'../api/auth.php',method:'POST',contentType:'application/json',data:JSON.stringify({action:'logout',csrf_token:PulsePoint.csrf()})}).done(()=>location.href='login.php'));$('.feedback-status').on('change',function(){$.ajax({url:'../api/feedback.php',method:'POST',contentType:'application/json',data:JSON.stringify({action:'status',id:$(this).data('id'),status:this.value,csrf_token:PulsePoint.csrf()})}).done(()=>PulsePoint.toast('Feedback status updated'))})</script></body></html>